export const scriptSrc = "\n    /* ============ DATA ============ */\n    const CATEGORIES = [\"All\", \"Grocery\", \"Electronics\", \"Home\", \"Fashion\", \"Beauty\"];\n    const PRODUCTS = [\n      { id: 1, title: \"Wireless ANC Headphones\", emoji: \"\ud83c\udfa7\", img: \"https://images.unsplash.com/photo-1599669454699-248893623440?w=400&q=80&auto=format&fit=crop\", cat: \"Electronics\", price: 2499, old: 3999, rating: 4.6, flash: true, eta: \"14 min\" },\n      { id: 2, title: \"Organic Avocado (4 pk)\", emoji: \"\ud83e\udd51\", img: \"https://images.unsplash.com/photo-1557925922-dac32ff4429f?w=400&q=80&auto=format&fit=crop\", cat: \"Grocery\", price: 199, old: null, rating: 4.4, flash: false, eta: \"11 min\" },\n      { id: 3, title: \"Smart Fitness Watch\", emoji: \"\u231a\", img: \"https://images.unsplash.com/photo-1551816230-ef5deaed4a26?w=400&q=80&auto=format&fit=crop\", cat: \"Electronics\", price: 3299, old: 4599, rating: 4.7, flash: true, eta: \"18 min\" },\n      { id: 4, title: \"Cold Brew Coffee Pack\", emoji: \"\u2615\", img: \"https://images.unsplash.com/photo-1536638455623-a35d0fa09ab9?w=400&q=80&auto=format&fit=crop\", cat: \"Grocery\", price: 349, old: null, rating: 4.3, flash: false, eta: \"9 min\" },\n      { id: 5, title: \"Ceramic Table Lamp\", emoji: \"\ud83d\udca1\", img: \"https://images.unsplash.com/photo-1570974802254-4b0ad1a755f5?w=400&q=80&auto=format&fit=crop\", cat: \"Home\", price: 1199, old: 1699, rating: 4.5, flash: false, eta: \"25 min\" },\n      { id: 6, title: \"Everyday Cotton Tee\", emoji: \"\ud83d\udc55\", img: \"https://images.unsplash.com/photo-1521572163474-6864f9cf17ab?w=400&q=80&auto=format&fit=crop\", cat: \"Fashion\", price: 449, old: 799, rating: 4.2, flash: true, eta: \"20 min\" },\n      { id: 7, title: \"Vitamin C Serum\", emoji: \"\ud83e\uddf4\", img: \"https://images.unsplash.com/photo-1723951174326-2a97221d3b7f?w=400&q=80&auto=format&fit=crop\", cat: \"Beauty\", price: 599, old: 899, rating: 4.6, flash: false, eta: \"13 min\" },\n      { id: 8, title: \"Mechanical Keyboard\", emoji: \"\u2328\ufe0f\", img: \"https://images.unsplash.com/photo-1669884210062-e3055c8c8f5d?w=400&q=80&auto=format&fit=crop\", cat: \"Electronics\", price: 3999, old: 5499, rating: 4.8, flash: false, eta: \"22 min\" },\n      { id: 9, title: \"Sourdough Loaf\", emoji: \"\ud83c\udf5e\", img: \"https://images.unsplash.com/photo-1620921586333-b7566c34550a?w=400&q=80&auto=format&fit=crop\", cat: \"Grocery\", price: 129, old: null, rating: 4.5, flash: false, eta: \"10 min\" },\n      { id: 10, title: \"Bluetooth Speaker\", emoji: \"\ud83d\udd0a\", img: \"https://images.unsplash.com/photo-1589003077984-894e133dabab?w=400&q=80&auto=format&fit=crop\", cat: \"Electronics\", price: 1799, old: 2299, rating: 4.4, flash: true, eta: \"16 min\" },\n      { id: 11, title: \"Scented Soy Candle\", emoji: \"\ud83d\udd6f\ufe0f\", img: \"https://images.unsplash.com/photo-1602874801007-bd458bb1b8b6?w=400&q=80&auto=format&fit=crop\", cat: \"Home\", price: 349, old: null, rating: 4.3, flash: false, eta: \"19 min\" },\n      { id: 12, title: \"Running Sneakers\", emoji: \"\ud83d\udc5f\", img: \"https://images.unsplash.com/photo-1562183241-b937e95585b6?w=400&q=80&auto=format&fit=crop\", cat: \"Fashion\", price: 2299, old: 2999, rating: 4.6, flash: false, eta: \"24 min\" },\n    ];\n\n    /* ============ API (real backend \u2014 auth/orders/payments are never sourced from localStorage) ============ */\n    // Point this at your backend. Same origin in production; a full URL during local dev\n    // if the frontend is served from a different port (see swiftcart-backend/.env.example).\n    const API_BASE = window.SWIFTCART_API_BASE || \"http://localhost:4000/api\";\n\n    async function apiFetch(path, options = {}) {\n      const res = await fetch(`${API_BASE}${path}`, {\n        credentials: \"include\", // send/receive the HttpOnly session cookie\n        headers: { \"Content-Type\": \"application/json\", ...(options.headers || {}) },\n        ...options,\n        body: options.body ? JSON.stringify(options.body) : undefined,\n      });\n      let data = null;\n      try { data = await res.json(); } catch (e) { /* empty body */ }\n      if (!res.ok) {\n        const err = new Error((data && data.error) || `Request failed (${res.status})`);\n        err.status = res.status;\n        err.details = data && data.details;\n        throw err;\n      }\n      return data;\n    }\n\n    /* ============ STATE (auth is server-side; cart stays in localStorage \u2014 it's not\n       trusted for pricing, the backend recomputes everything at checkout) ============ */\n    const LS_CART = \"swiftcart_cart\";\n\n    function lsGet(key, fallback) {\n      try {\n        const raw = localStorage.getItem(key);\n        return raw ? JSON.parse(raw) : fallback;\n      } catch (e) { return fallback; } // storage unavailable (private mode, disabled, etc.) \u2014 fall back to defaults\n    }\n    function lsSet(key, value) {\n      try { localStorage.setItem(key, JSON.stringify(value)); }\n      catch (e) { /* storage unavailable \u2014 state still works for this tab session */ }\n    }\n\n    let _session = null; // populated from GET /api/auth/me on load \u2014 never trust a locally-cached role/session\n    let _cart = lsGet(LS_CART, []);\n\n    function getSession() { return _session; }\n    function setSession(u) { _session = u || null; }\n    function getCart() { return _cart; }\n    function saveCart(c) { _cart = c; lsSet(LS_CART, _cart); renderCart(); }\n\n    async function restoreSession() {\n      try {\n        const { user } = await apiFetch(\"/auth/me\");\n        setSession(user);\n        if (typeof user.walletBalance === \"number\") _walletBalance = user.walletBalance;\n      } catch (e) {\n        setSession(null); // 401 (or backend unreachable) \u2192 logged-out state, same as a fresh visitor\n      }\n      renderAuthUI();\n    }\n\n    let currentCategory = \"All\";\n    let authMode = \"login\";\n    let _address = null; // { name, phone, line } \u2014 last used at checkout\n    let _wishlist = []; // array of product ids\n\n    /* ============ DELIVERY ============ */\n    const DELIVERY_FEE = 40;\n    const FREE_DELIVERY_THRESHOLD = 200;\n    function getDelivery(subtotal) {\n      const fee = subtotal >= FREE_DELIVERY_THRESHOLD ? 0 : DELIVERY_FEE;\n      const remaining = Math.max(0, FREE_DELIVERY_THRESHOLD - subtotal);\n      return { fee, remaining };\n    }\n\n    /* ============ COUPONS ============ */\n    // This table is used for the pre-checkout discount PREVIEW only (cart screen, coupon list).\n    // It is never trusted for the actual charge \u2014 POST /api/orders recomputes the discount\n    // server-side from the real Coupon collection (see swiftcart-backend/routes/orders.js),\n    // so if an admin adds/disables a coupon here, the preview can lag until this table is\n    // synced, but a customer can never get a discount the backend didn't independently approve.\n    const COUPONS = [\n      { code: \"WELCOME10\", label: \"10% off\", desc: \"10% off your order, no minimum\", type: \"percent\", value: 10, minSubtotal: 0 },\n      { code: \"FLAT50\", label: \"\u20b950 off\", desc: \"Flat \u20b950 off on orders above \u20b9300\", type: \"flat\", value: 50, minSubtotal: 300 },\n      { code: \"SWIFT20\", label: \"20% off\", desc: \"20% off on orders above \u20b9500 (max \u20b9150)\", type: \"percent\", value: 20, minSubtotal: 500, maxDiscount: 150 },\n    ];\n    let _appliedCoupon = null; // one of COUPONS, or null\n    let _savedCoupons = []; // codes the user saved for future use (not necessarily valid/eligible yet)\n\n    function getDiscount(subtotal) {\n      if (!_appliedCoupon || subtotal < _appliedCoupon.minSubtotal) return 0;\n      let d = _appliedCoupon.type === \"flat\" ? _appliedCoupon.value : Math.round(subtotal * _appliedCoupon.value / 100);\n      if (_appliedCoupon.maxDiscount) d = Math.min(d, _appliedCoupon.maxDiscount);\n      return Math.min(d, subtotal);\n    }\n\n    function applyCouponCode(rawCode) {\n      const code = (rawCode || \"\").trim().toUpperCase();\n      const errEl = document.getElementById(\"couponError\");\n      if (errEl) errEl.textContent = \"\";\n      if (!code) return;\n      const cart = getCart();\n      const subtotal = cart.reduce((s, l) => { const p = PRODUCTS.find(pp => pp.id === l.id); return s + p.price * l.qty; }, 0);\n      const found = COUPONS.find(c => c.code === code);\n      if (!found) {\n        if (errEl) errEl.textContent = \"Invalid coupon code.\";\n        else toast(\"Invalid coupon code\");\n        return;\n      }\n      if (subtotal < found.minSubtotal) {\n        const msg = `Add \u20b9${found.minSubtotal - subtotal} more to use ${found.code}`;\n        if (errEl) errEl.textContent = msg;\n        else toast(msg);\n        return;\n      }\n      _appliedCoupon = found;\n      toast(`${found.code} applied \ud83c\udf89`);\n      renderCart();\n      if (document.getElementById(\"couponsOverlay\").classList.contains(\"show\")) closeCoupons();\n      openCart();\n    }\n\n    function removeCoupon() {\n      _appliedCoupon = null;\n      renderCart();\n      toast(\"Coupon removed\");\n    }\n\n    function saveCouponForLater(rawCode) {\n      const code = (rawCode || \"\").trim().toUpperCase();\n      const errEl = document.getElementById(\"saveCouponError\");\n      if (errEl) errEl.textContent = \"\";\n      if (!code) {\n        if (errEl) errEl.textContent = \"Enter a code to save.\";\n        return;\n      }\n      if (_savedCoupons.includes(code)) {\n        if (errEl) errEl.textContent = \"This code is already saved.\";\n        return;\n      }\n      _savedCoupons.push(code);\n      const input = document.getElementById(\"saveCouponInput\");\n      if (input) input.value = \"\";\n      renderCoupons();\n      toast(`${code} saved for later`);\n    }\n\n    function removeSavedCoupon(code) {\n      _savedCoupons = _savedCoupons.filter(c => c !== code);\n      renderCoupons();\n      toast(\"Saved code removed\");\n    }\n\n    /* ============ TOAST ============ */\n    function toast(msg) {\n      const t = document.getElementById(\"toast\");\n      t.textContent = msg;\n      t.classList.add(\"show\");\n      clearTimeout(window._toastTimer);\n      window._toastTimer = setTimeout(() => t.classList.remove(\"show\"), 2200);\n    }\n\n    function bumpCartIcon() {\n      const btn = document.getElementById(\"cartBtn\");\n      btn.classList.remove(\"bump\");\n      void btn.offsetWidth; // restart animation if triggered again quickly\n      btn.classList.add(\"bump\");\n    }\n\n    /* ============ RENDER: NAV AUTH STATE ============ */\n    function renderAuthUI() {\n      const user = getSession();\n      const signInBtn = document.getElementById(\"signInBtn\");\n      const menuWrap = document.getElementById(\"userMenuWrap\");\n      const mobileBtn = document.getElementById(\"mobileAccountBtn\");\n      if (user) {\n        signInBtn.style.display = \"none\";\n        menuWrap.style.display = \"block\";\n        document.getElementById(\"userAvatar\").textContent = user.name.charAt(0).toUpperCase();\n        document.getElementById(\"userNameLabel\").textContent = user.name;\n        document.getElementById(\"menuName\").textContent = user.name;\n        document.getElementById(\"menuEmail\").textContent = user.email;\n        mobileBtn.classList.add(\"logged-in\");\n        document.getElementById(\"mobileAvatarDot\").textContent = user.name.charAt(0).toUpperCase();\n      } else {\n        signInBtn.style.display = \"\";\n        menuWrap.style.display = \"none\";\n        document.getElementById(\"userMenu\").classList.remove(\"open\");\n        mobileBtn.classList.remove(\"logged-in\");\n      }\n    }\n\n    /* ============ CATEGORIES + GRID ============ */\n    function renderCategories() {\n      const wrap = document.getElementById(\"categories\");\n      wrap.innerHTML = CATEGORIES.map(c =>\n        `<button class=\"cat-pill ${c === currentCategory ? 'active' : ''}\" data-cat=\"${c}\">${c}</button>`\n      ).join(\"\");\n      wrap.querySelectorAll(\".cat-pill\").forEach(btn => {\n        btn.onclick = () => { currentCategory = btn.dataset.cat; renderCategories(); renderGrid(); };\n      });\n    }\n\n    let lastQuery = \"\";\n    function renderGrid(query) {\n      if (query !== undefined) lastQuery = query;\n      const grid = document.getElementById(\"productGrid\");\n      const q = (lastQuery || \"\").trim().toLowerCase();\n      let items = PRODUCTS.filter(p => currentCategory === \"All\" || p.cat === currentCategory);\n      if (q) items = items.filter(p => p.title.toLowerCase().includes(q));\n      document.getElementById(\"gridTitle\").textContent = q ? `Results for \"${q}\"` : \"Trending right now\";\n\n      grid.innerHTML = items.map(p => `\n    <div class=\"card\">\n      <div class=\"card-img\">\n        ${p.flash ? `<span class=\"flash-tag\"><svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12.586 2.586A2 2 0 0 0 11.172 2H4a2 2 0 0 0-2 2v7.172a2 2 0 0 0 .586 1.414l8.704 8.704a2.426 2.426 0 0 0 3.42 0l6.58-6.58a2.426 2.426 0 0 0 0-3.42Z\"/><circle cx=\"7.5\" cy=\"7.5\" r=\".5\" fill=\"currentColor\"/></svg>SALE</span>` : \"\"}\n        <button class=\"wish-btn ${_wishlist.includes(p.id) ? \"active\" : \"\"}\" data-id=\"${p.id}\" aria-label=\"Add to wishlist\">\n          <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"${_wishlist.includes(p.id) ? \"currentColor\" : \"none\"}\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M19 14c1.5-1.5 3-3.4 3-5.5A5.5 5.5 0 0 0 12 5a5.5 5.5 0 0 0-10 3.5C2 10.6 3.5 12.5 5 14l7 7Z\"/></svg>\n        </button>\n        <img src=\"${p.img}\" alt=\"${p.title}\" loading=\"lazy\" onerror=\"this.replaceWith(Object.assign(document.createElement('span'),{style:'font-size:40px',textContent:'${p.emoji}'}))\" />\n      </div>\n      <div class=\"card-body\">\n        <div class=\"title\">${p.title}</div>\n        <div class=\"meta\">\u2b50 ${p.rating} \u00b7 ${p.eta} delivery</div>\n        <div class=\"price-row\">\n          <span class=\"price\">\u20b9${p.price}</span>\n          ${p.old ? `<span class=\"price-old\">\u20b9${p.old}</span>` : \"\"}\n        </div>\n        <button class=\"add-btn\" data-id=\"${p.id}\">Add to cart</button>\n      </div>\n    </div>\n  `).join(\"\") || `<p style=\"color:#94A3B8;grid-column:1/-1\">No products match that search.</p>`;\n\n      grid.querySelectorAll(\".add-btn\").forEach(btn => {\n        btn.onclick = () => addToCart(parseInt(btn.dataset.id));\n      });\n      grid.querySelectorAll(\".wish-btn\").forEach(btn => {\n        btn.onclick = () => toggleWishlist(parseInt(btn.dataset.id));\n      });\n    }\n\n    /* ============ CART ============ */\n    function addToCart(id) {\n      const cart = getCart();\n      const line = cart.find(l => l.id === id);\n      if (line) line.qty += 1;\n      else cart.push({ id, qty: 1 });\n      saveCart(cart);\n      toast(\"Added to cart\");\n      bumpCartIcon();\n    }\n    function setQty(id, qty) {\n      let cart = getCart();\n      if (qty <= 0) cart = cart.filter(l => l.id !== id);\n      else cart = cart.map(l => l.id === id ? { ...l, qty } : l);\n      saveCart(cart);\n    }\n    function renderCart() {\n      const cart = getCart();\n      const body = document.getElementById(\"cartBody\");\n      const foot = document.getElementById(\"cartFoot\");\n      const badge = document.getElementById(\"cartBadge\");\n      const count = cart.reduce((s, l) => s + l.qty, 0);\n\n      badge.style.display = count > 0 ? \"flex\" : \"none\";\n      badge.textContent = count;\n\n      if (cart.length === 0) {\n        body.innerHTML = `<div class=\"empty-cart\"><div class=\"e\">\ud83d\uded2</div>Your cart is empty.<br/>Go find something fast.</div>`;\n        foot.style.display = \"none\";\n        return;\n      }\n      foot.style.display = \"block\";\n      let subtotal = 0;\n      body.innerHTML = cart.map(l => {\n        const p = PRODUCTS.find(pp => pp.id === l.id);\n        subtotal += p.price * l.qty;\n        return `\n      <div class=\"cart-line\">\n        <div class=\"cart-thumb\"><img src=\"${p.img}\" alt=\"${p.title}\" onerror=\"this.replaceWith(document.createTextNode('${p.emoji}'))\" /></div>\n        <div class=\"cart-info\">\n          <div class=\"t\">${p.title}</div>\n          <div class=\"p\">\u20b9${p.price}</div>\n          <div class=\"qty\">\n            <button data-id=\"${p.id}\" data-d=\"-1\">\u2212</button>\n            <span>${l.qty}</span>\n            <button data-id=\"${p.id}\" data-d=\"1\">+</button>\n          </div>\n        </div>\n      </div>`;\n      }).join(\"\");\n\n      const { fee, remaining } = getDelivery(subtotal);\n      const noteEl = document.getElementById(\"deliveryNote\");\n      if (remaining > 0) {\n        const pct = Math.min(100, Math.round((subtotal / FREE_DELIVERY_THRESHOLD) * 100));\n        noteEl.className = \"delivery-note pending\";\n        noteEl.innerHTML = `\ud83d\udef5 Add \u20b9${remaining} more for FREE delivery<div class=\"delivery-bar\"><span style=\"width:${pct}%\"></span></div>`;\n      } else {\n        noteEl.className = \"delivery-note unlocked\";\n        noteEl.innerHTML = `\ud83c\udf89 You've unlocked FREE delivery!`;\n      }\n\n      // if applied coupon no longer qualifies (e.g. items removed), drop it silently\n      if (_appliedCoupon && subtotal < _appliedCoupon.minSubtotal) _appliedCoupon = null;\n      const discount = getDiscount(subtotal);\n\n      const couponBox = document.getElementById(\"couponBox\");\n      if (_appliedCoupon) {\n        couponBox.innerHTML = `\n      <div class=\"coupon-applied\">\n        <span>\ud83c\udff7\ufe0f <b>${_appliedCoupon.code}</b> applied \u2014 you saved \u20b9${discount}</span>\n        <button id=\"removeCouponBtn\" aria-label=\"Remove coupon\">\u2715</button>\n      </div>`;\n        document.getElementById(\"removeCouponBtn\").onclick = removeCoupon;\n      } else {\n        couponBox.innerHTML = `\n      <div class=\"coupon-input-row\">\n        <input type=\"text\" id=\"couponInput\" placeholder=\"Enter coupon code\" autocomplete=\"off\"/>\n        <button id=\"couponApplyBtn\" class=\"btn-secondary\">Apply</button>\n      </div>\n      <div class=\"coupon-error\" id=\"couponError\"></div>\n      <div class=\"coupon-avail\">\n        ${COUPONS.map(c => {\n          const eligible = subtotal >= c.minSubtotal;\n          return `\n            <button class=\"coupon-chip ${eligible ? \"\" : \"disabled\"}\" data-code=\"${c.code}\" ${eligible ? \"\" : \"disabled\"}>\n              <span class=\"code\">${c.code}</span>\n              <span class=\"desc\">${eligible ? c.desc : `Add \u20b9${c.minSubtotal - subtotal} more to unlock`}</span>\n            </button>`;\n        }).join(\"\")}\n      </div>`;\n        document.getElementById(\"couponApplyBtn\").onclick = () => applyCouponCode(document.getElementById(\"couponInput\").value);\n        document.getElementById(\"couponInput\").addEventListener(\"keydown\", (e) => {\n          if (e.key === \"Enter\") applyCouponCode(e.target.value);\n        });\n        couponBox.querySelectorAll(\".coupon-chip\").forEach(btn => {\n          if (btn.disabled) return;\n          btn.onclick = () => applyCouponCode(btn.dataset.code);\n        });\n      }\n\n      document.getElementById(\"cartSubtotal\").textContent = `\u20b9${subtotal}`;\n      document.getElementById(\"cartDelivery\").textContent = fee === 0 ? \"FREE\" : `\u20b9${fee}`;\n\n      const discountRow = document.getElementById(\"discountRow\");\n      if (discount > 0) {\n        discountRow.style.display = \"flex\";\n        document.getElementById(\"cartDiscount\").textContent = `\u2212\u20b9${discount}`;\n      } else {\n        discountRow.style.display = \"none\";\n      }\n\n      document.getElementById(\"cartTotal\").textContent = `\u20b9${Math.max(0, subtotal + fee - discount)}`;\n\n\n      body.querySelectorAll(\".qty button\").forEach(btn => {\n        btn.onclick = () => {\n          const id = parseInt(btn.dataset.id);\n          const d = parseInt(btn.dataset.d);\n          const line = getCart().find(l => l.id === id);\n          setQty(id, line.qty + d);\n        };\n      });\n    }\n    function openCart() { document.getElementById(\"overlay\").classList.add(\"show\"); document.getElementById(\"drawer\").classList.add(\"show\"); }\n    function closeCart() { document.getElementById(\"overlay\").classList.remove(\"show\"); document.getElementById(\"drawer\").classList.remove(\"show\"); }\n\n    /* ============ AUTH MODAL ============ */\n    function openAuth(mode) {\n      authMode = mode || \"login\";\n      updateAuthModal();\n      document.getElementById(\"authOverlay\").classList.add(\"show\");\n    }\n    function closeAuth() {\n      document.getElementById(\"authOverlay\").classList.remove(\"show\");\n      document.getElementById(\"authError\").style.display = \"none\";\n      document.getElementById(\"authForm\").reset();\n    }\n    function updateAuthModal() {\n      const isLogin = authMode === \"login\";\n      document.getElementById(\"authTitle\").textContent = isLogin ? \"Welcome back\" : \"Create your account\";\n      document.getElementById(\"authSub\").innerHTML = isLogin\n        ? `New to SwiftCart? <button id=\"authToggle\">Create one</button>`\n        : `Already have an account? <button id=\"authToggle\">Sign in</button>`;\n      document.getElementById(\"nameField\").style.display = isLogin ? \"none\" : \"block\";\n      document.getElementById(\"authName\").required = !isLogin;\n      document.getElementById(\"authSubmit\").textContent = isLogin ? \"Sign in\" : \"Create account\";\n      document.getElementById(\"authError\").style.display = \"none\";\n      document.getElementById(\"authToggle\").onclick = () => { authMode = isLogin ? \"register\" : \"login\"; updateAuthModal(); };\n    }\n\n    async function handleAuthSubmit(e) {\n      if (e && e.preventDefault) e.preventDefault();\n      const name = document.getElementById(\"authName\").value.trim();\n      const email = document.getElementById(\"authEmail\").value.trim().toLowerCase();\n      const password = document.getElementById(\"authPassword\").value;\n      const errEl = document.getElementById(\"authError\");\n      errEl.style.display = \"none\";\n\n      if (!email || !password) {\n        errEl.textContent = \"Please fill in both email and password.\";\n        errEl.style.display = \"block\";\n        return;\n      }\n      if (password.length < 8) {\n        errEl.textContent = \"Password must be at least 8 characters.\";\n        errEl.style.display = \"block\";\n        return;\n      }\n      if (authMode === \"register\" && !name) {\n        errEl.textContent = \"Please enter your name.\";\n        errEl.style.display = \"block\";\n        return;\n      }\n\n      const submitBtn = document.getElementById(\"authSubmit\");\n      submitBtn.disabled = true;\n\n      try {\n        if (authMode === \"register\") {\n          const { user } = await apiFetch(\"/auth/register\", { method: \"POST\", body: { name, email, password } });\n          setSession(user);\n          _walletBalance = user.walletBalance || 0;\n          toast(`Welcome, ${user.name}!`);\n        } else {\n          const { user } = await apiFetch(\"/auth/login\", { method: \"POST\", body: { email, password } });\n          setSession(user);\n          _walletBalance = user.walletBalance || 0;\n          toast(`Welcome back, ${user.name}!`);\n        }\n        renderAuthUI();\n        closeAuth();\n      } catch (err) {\n        errEl.textContent = err.status === 429\n          ? \"Too many attempts. Please wait a bit and try again.\"\n          : (err.message || \"Something went wrong. Please try again.\");\n        errEl.style.display = \"block\";\n      } finally {\n        submitBtn.disabled = false;\n      }\n    }\n\n    async function logout() {\n      try { await apiFetch(\"/auth/logout\", { method: \"POST\" }); }\n      catch (e) { /* even if the network call fails, drop the local session state below */ }\n      setSession(null);\n      renderAuthUI();\n      toast(\"Signed out\");\n    }\n\n    /* ============ FLASH SALE TIMER ============ */\n    function startTimer() {\n      let total = 2 * 3600 + 14 * 60 + 55;\n      function tick() {\n        if (total <= 0) { total = 3 * 3600; }\n        total--;\n        const h = Math.floor(total / 3600), m = Math.floor((total % 3600) / 60), s = total % 60;\n        document.getElementById(\"th\").firstChild.nodeValue = String(h).padStart(2, \"0\");\n        document.getElementById(\"tm\").firstChild.nodeValue = String(m).padStart(2, \"0\");\n        document.getElementById(\"ts\").firstChild.nodeValue = String(s).padStart(2, \"0\");\n      }\n      tick();\n      setInterval(tick, 1000);\n    }\n\n    function scrollToShop() { document.getElementById(\"shop\").scrollIntoView({ behavior: \"smooth\" }); }\n\n    /* ============ ADDRESS BOOK ============ */\n    let _addresses = []; // { id, name, phone, line }\n    let _addrCounter = 1;\n    let _addrMode = \"checkout\"; // \"checkout\" | \"add\" | \"edit\"\n    let _editingAddrId = null;\n\n    function openAddress(mode) {\n      _addrMode = mode || \"checkout\";\n      document.getElementById(\"addrName\").value = \"\";\n      document.getElementById(\"addrPhone\").value = \"\";\n      document.getElementById(\"addrLine\").value = \"\";\n      document.getElementById(\"addrError\").style.display = \"none\";\n\n      const picker = document.getElementById(\"addrPicker\");\n      const form = document.getElementById(\"addrForm\");\n\n      if (_addrMode === \"checkout\" && _addresses.length > 0) {\n        renderAddrPicker();\n        picker.style.display = \"block\";\n        form.style.display = \"none\";\n        document.getElementById(\"addrTitle\").textContent = \"Choose delivery address\";\n        document.getElementById(\"addrSub\").textContent = \"Select a saved address, or add a new one.\";\n        document.getElementById(\"addrOverlay\").classList.add(\"show\");\n        return;\n      }\n\n      picker.style.display = \"none\";\n      form.style.display = \"block\";\n\n      if (_addrMode === \"edit\") {\n        const a = _addresses.find(x => x.id === _editingAddrId);\n        if (a) {\n          document.getElementById(\"addrName\").value = a.name;\n          document.getElementById(\"addrPhone\").value = a.phone;\n          document.getElementById(\"addrLine\").value = a.line;\n        }\n        document.getElementById(\"addrTitle\").textContent = \"Edit address\";\n        document.getElementById(\"addrSub\").textContent = \"Update the details below.\";\n        document.getElementById(\"addrSubmit\").textContent = \"Save changes\";\n      } else if (_addrMode === \"add\") {\n        document.getElementById(\"addrTitle\").textContent = \"Add a new address\";\n        document.getElementById(\"addrSub\").textContent = \"Save an address for faster checkout.\";\n        document.getElementById(\"addrSubmit\").textContent = \"Save address\";\n      } else {\n        if (_address) {\n          document.getElementById(\"addrName\").value = _address.name;\n          document.getElementById(\"addrPhone\").value = _address.phone;\n          document.getElementById(\"addrLine\").value = _address.line;\n        }\n        document.getElementById(\"addrTitle\").textContent = \"Delivery address\";\n        document.getElementById(\"addrSub\").textContent = \"Where should we drop this off?\";\n        document.getElementById(\"addrSubmit\").textContent = \"Confirm & place order\";\n      }\n      document.getElementById(\"addrOverlay\").classList.add(\"show\");\n    }\n\n    function renderAddrPicker() {\n      const wrap = document.getElementById(\"addrPicker\");\n      wrap.innerHTML = `<div class=\"addr-pick-list\">${_addresses.map(a => `\n    <button class=\"addr-pick-card\" data-id=\"${a.id}\" type=\"button\">\n      <div class=\"addr-pick-top\">\n        <span class=\"addr-pick-name\">${a.name}</span>\n        ${_address && _address.id === a.id ? '<span class=\"addr-pick-badge\">DEFAULT</span>' : \"\"}\n      </div>\n      <div class=\"addr-pick-phone\">${a.phone}</div>\n      <div class=\"addr-pick-line\">${a.line}</div>\n    </button>`).join(\"\")}\n  </div>\n  <button class=\"addr-add-new\" id=\"addrPickerAddNew\" type=\"button\">+ Add a new address</button>`;\n\n      wrap.querySelectorAll(\".addr-pick-card\").forEach(btn => {\n        btn.onclick = () => {\n          const a = _addresses.find(x => x.id === parseInt(btn.dataset.id));\n          if (!a) return;\n          _address = { ...a };\n          closeAddress();\n          openPaymentMethod();\n        };\n      });\n      document.getElementById(\"addrPickerAddNew\").onclick = () => {\n        _addrMode = \"checkout\";\n        document.getElementById(\"addrPicker\").style.display = \"none\";\n        document.getElementById(\"addrForm\").style.display = \"block\";\n        document.getElementById(\"addrName\").value = \"\";\n        document.getElementById(\"addrPhone\").value = \"\";\n        document.getElementById(\"addrLine\").value = \"\";\n        document.getElementById(\"addrTitle\").textContent = \"Delivery address\";\n        document.getElementById(\"addrSub\").textContent = \"Where should we drop this off?\";\n        document.getElementById(\"addrSubmit\").textContent = \"Confirm & place order\";\n      };\n    }\n    function closeAddress() { document.getElementById(\"addrOverlay\").classList.remove(\"show\"); }\n\n    function handleAddressSubmit() {\n      const name = document.getElementById(\"addrName\").value.trim();\n      const phone = document.getElementById(\"addrPhone\").value.trim();\n      const line = document.getElementById(\"addrLine\").value.trim();\n      const errEl = document.getElementById(\"addrError\");\n\n      if (!name || !phone || !line) {\n        errEl.textContent = \"Please fill in your name, phone, and address.\";\n        errEl.style.display = \"block\";\n        return;\n      }\n      if (phone.replace(/\\D/g, \"\").length < 7) {\n        errEl.textContent = \"Please enter a valid phone number.\";\n        errEl.style.display = \"block\";\n        return;\n      }\n\n      if (_addrMode === \"edit\") {\n        const a = _addresses.find(x => x.id === _editingAddrId);\n        if (a) { a.name = name; a.phone = phone; a.line = line; }\n        if (_address && _address.id === _editingAddrId) _address = { ...a };\n        closeAddress();\n        renderAddressBook();\n        toast(\"Address updated\");\n        return;\n      }\n\n      if (_addrMode === \"add\") {\n        const newAddr = { id: _addrCounter++, name, phone, line };\n        _addresses.push(newAddr);\n        if (!_address) _address = { ...newAddr };\n        closeAddress();\n        renderAddressBook();\n        toast(\"Address saved\");\n        return;\n      }\n\n      // checkout mode \u2014 save into the book (reusing a matching one) then place the order\n      let match = _addresses.find(a => a.line.trim().toLowerCase() === line.toLowerCase());\n      if (match) { match.name = name; match.phone = phone; }\n      else { match = { id: _addrCounter++, name, phone, line }; _addresses.push(match); }\n      _address = { ...match };\n      closeAddress();\n      openPaymentMethod();\n    }\n\n    function openAddressBook() {\n      renderAddressBook();\n      document.getElementById(\"addrBookOverlay\").classList.add(\"show\");\n    }\n    function closeAddressBook() { document.getElementById(\"addrBookOverlay\").classList.remove(\"show\"); }\n\n    function renderAddressBook() {\n      const list = document.getElementById(\"addrBookList\");\n      if (_addresses.length === 0) {\n        list.innerHTML = `<div class=\"orders-empty\" style=\"padding:40px 10px\">\n      <div class=\"e\">\ud83d\udccd</div>No saved addresses yet.\n    </div>`;\n        return;\n      }\n      list.innerHTML = _addresses.map(a => `\n    <div class=\"order-card\">\n      <div class=\"order-card-top\">\n        <div>\n          <div class=\"oid\" style=\"font-size:14px\">${a.name} ${_address && _address.id === a.id ? '<span class=\"addr-default\">DEFAULT</span>' : \"\"}</div>\n          <div class=\"odate\">${a.phone}</div>\n        </div>\n        <div class=\"addr-actions\">\n          <button class=\"edit\" data-id=\"${a.id}\" aria-label=\"Edit\">\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7\"/><path d=\"M18.5 2.5a2.1 2.1 0 0 1 3 3L12 15l-4 1 1-4Z\"/></svg>\n          </button>\n          <button class=\"del\" data-id=\"${a.id}\" aria-label=\"Delete\">\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M3 6h18\"/><path d=\"M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2\"/></svg>\n          </button>\n        </div>\n      </div>\n      <div class=\"order-items\" style=\"margin-bottom:0\">${a.line}</div>\n    </div>\n  `).join(\"\");\n\n      list.querySelectorAll(\".edit\").forEach(btn => {\n        btn.onclick = () => { _editingAddrId = parseInt(btn.dataset.id); openAddress(\"edit\"); };\n      });\n      list.querySelectorAll(\".del\").forEach(btn => {\n        btn.onclick = () => {\n          const id = parseInt(btn.dataset.id);\n          _addresses = _addresses.filter(a => a.id !== id);\n          if (_address && _address.id === id) _address = _addresses[0] ? { ..._addresses[0] } : null;\n          renderAddressBook();\n          toast(\"Address removed\");\n        };\n      });\n    }\n\n    /* ============ PAYMENT SETTINGS ============ */\n    let _paymentMethods = []; // { id, type: \"upi\"|\"card\", detail, label }\n    let _pmCounter = 1;\n\n    function openPaymentSettings() {\n      renderPaymentSettings();\n      document.getElementById(\"paymentOverlay\").classList.add(\"show\");\n    }\n    function closePaymentSettings() { document.getElementById(\"paymentOverlay\").classList.remove(\"show\"); }\n\n    function renderPaymentSettings() {\n      const list = document.getElementById(\"paymentList\");\n      if (_paymentMethods.length === 0) {\n        list.innerHTML = `<div class=\"orders-empty\" style=\"padding:40px 10px\">\n      <div class=\"e\">\ud83d\udcb3</div>No saved payment methods yet.\n    </div>`;\n        return;\n      }\n      list.innerHTML = _paymentMethods.map(pm => `\n    <div class=\"order-card\">\n      <div class=\"order-card-top\">\n        <div>\n          <div class=\"oid\" style=\"font-size:14px\">${pm.type === \"upi\" ? \"\ud83d\udcf1 \" + pm.detail : \"\ud83d\udcb3 \" + pm.label}</div>\n          <div class=\"odate\">${pm.type === \"upi\" ? \"UPI ID\" : pm.detail}</div>\n        </div>\n        <div class=\"addr-actions\">\n          <button class=\"del\" data-id=\"${pm.id}\" aria-label=\"Remove\">\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M3 6h18\"/><path d=\"M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2\"/></svg>\n          </button>\n        </div>\n      </div>\n    </div>\n  `).join(\"\");\n\n      list.querySelectorAll(\".del\").forEach(btn => {\n        btn.onclick = () => {\n          const id = parseInt(btn.dataset.id);\n          _paymentMethods = _paymentMethods.filter(p => p.id !== id);\n          renderPaymentSettings();\n          toast(\"Payment method removed\");\n        };\n      });\n    }\n\n    function openAddUpi() {\n      document.getElementById(\"pmUpiId\").value = \"\";\n      document.getElementById(\"addUpiError\").style.display = \"none\";\n      document.getElementById(\"addUpiOverlay\").classList.add(\"show\");\n    }\n    function closeAddUpi() {\n      document.getElementById(\"addUpiOverlay\").classList.remove(\"show\");\n      if (_pendingCheckoutMethod === \"upi\") {\n        _pendingCheckoutMethod = null;\n        openPaymentMethod(true);\n      }\n    }\n\n    function handleAddUpiSubmit() {\n      const val = document.getElementById(\"pmUpiId\").value.trim();\n      const errEl = document.getElementById(\"addUpiError\");\n      if (!val || !/^[\\w.\\-]+@[\\w.\\-]+$/.test(val)) {\n        errEl.textContent = \"Please enter a valid UPI ID (e.g. name@upi).\";\n        errEl.style.display = \"block\";\n        return;\n      }\n      if (_paymentMethods.some(p => p.type === \"upi\" && p.detail.toLowerCase() === val.toLowerCase())) {\n        errEl.textContent = \"This UPI ID is already saved.\";\n        errEl.style.display = \"block\";\n        return;\n      }\n      errEl.style.display = \"none\";\n      _paymentMethods.push({ id: _pmCounter++, type: \"upi\", detail: val });\n      closeAddUpi();\n      renderPaymentSettings();\n      toast(\"UPI ID saved\");\n    }\n\n    function openAddCard() {\n      [\"pmCardName\", \"pmCardNumber\", \"pmCardExpiry\", \"pmCardCvv\"].forEach(id => document.getElementById(id).value = \"\");\n      document.getElementById(\"addCardError\").style.display = \"none\";\n      document.getElementById(\"addCardOverlay\").classList.add(\"show\");\n    }\n    function closeAddCard() {\n      document.getElementById(\"addCardOverlay\").classList.remove(\"show\");\n      if (_pendingCheckoutMethod === \"card\") {\n        _pendingCheckoutMethod = null;\n        openPaymentMethod(true);\n      }\n    }\n\n    function handleAddCardSubmit() {\n      const name = document.getElementById(\"pmCardName\").value.trim();\n      const numberRaw = document.getElementById(\"pmCardNumber\").value.replace(/\\s+/g, \"\");\n      const expiry = document.getElementById(\"pmCardExpiry\").value.trim();\n      const cvv = document.getElementById(\"pmCardCvv\").value.trim();\n      const errEl = document.getElementById(\"addCardError\");\n\n      if (!name) {\n        errEl.textContent = \"Please enter the name on the card.\";\n        errEl.style.display = \"block\";\n        return;\n      }\n      if (!/^\\d{13,19}$/.test(numberRaw)) {\n        errEl.textContent = \"Please enter a valid card number.\";\n        errEl.style.display = \"block\";\n        return;\n      }\n      if (!/^(0[1-9]|1[0-2])\\/\\d{2}$/.test(expiry)) {\n        errEl.textContent = \"Please enter a valid expiry date (MM/YY).\";\n        errEl.style.display = \"block\";\n        return;\n      }\n      if (!/^\\d{3,4}$/.test(cvv)) {\n        errEl.textContent = \"Please enter a valid CVV.\";\n        errEl.style.display = \"block\";\n        return;\n      }\n      errEl.style.display = \"none\";\n      const last4 = numberRaw.slice(-4);\n      _paymentMethods.push({\n        id: _pmCounter++,\n        type: \"card\",\n        label: `Card \u2022\u2022\u2022\u2022 ${last4}`,\n        detail: `${name} \u00b7 Expires ${expiry}`\n      });\n      closeAddCard();\n      renderPaymentSettings();\n      toast(\"Card saved\");\n    }\n\n    /* ============ ORDER TRACKING ============ */\n    let _trackTimers = [];\n    // Orders themselves now live in MongoDB (see /api/orders, /api/users/me/orders) \u2014 no local array.\n\n    /* ============ PAYMENT METHOD (CHECKOUT) ============ */\n    const PAY_METHOD_LABELS = { upi: \"UPI\", wallet: \"SwiftCart Wallet\", card: \"Card\", cod: \"Cash on Delivery\" };\n    let _payMethod = \"upi\"; // \"upi\" | \"wallet\" | \"card\" | \"cod\"\n    let _payMethodTotal = 0;\n    let _pendingCheckoutMethod = null; // set while we've bounced the user to Add UPI/Card mid-checkout\n\n    function getCheckoutTotal() {\n      const cart = getCart();\n      const subtotal = cart.reduce((s, l) => { const p = PRODUCTS.find(pp => pp.id === l.id); return s + p.price * l.qty; }, 0);\n      const { fee } = getDelivery(subtotal);\n      const discount = getDiscount(subtotal);\n      return Math.max(0, subtotal + fee - discount);\n    }\n\n    function openPaymentMethod(preserveMethod) {\n      _payMethodTotal = getCheckoutTotal();\n      document.getElementById(\"payMethodTotal\").textContent = `\u20b9${_payMethodTotal}`;\n      document.getElementById(\"payMethodError\").style.display = \"none\";\n      if (!preserveMethod) {\n        // default to wallet if it covers the total, otherwise UPI\n        _payMethod = (_walletBalance >= _payMethodTotal && _payMethodTotal > 0) ? \"wallet\" : \"upi\";\n      }\n      renderPaymentMethodOptions();\n      document.getElementById(\"payMethodOverlay\").classList.add(\"show\");\n    }\n    function closePaymentMethod() { document.getElementById(\"payMethodOverlay\").classList.remove(\"show\"); }\n\n    function renderPaymentMethodOptions() {\n      const list = document.getElementById(\"payMethodList\");\n      const total = _payMethodTotal;\n      const walletOk = _walletBalance >= total;\n      const savedUpi = _paymentMethods.find(p => p.type === \"upi\");\n      const savedCard = _paymentMethods.find(p => p.type === \"card\");\n\n      const options = [\n        { id: \"upi\", emoji: \"\ud83d\udcf1\", title: \"UPI\", sub: savedUpi ? `Pay using ${savedUpi.detail}` : \"No UPI ID saved \u2014 you'll be asked to add one\", disabled: false },\n        { id: \"wallet\", emoji: \"\ud83d\udc5b\", title: \"SwiftCart Wallet\", sub: `Balance \u20b9${_walletBalance}${walletOk ? \"\" : \" \u2014 insufficient balance\"}`, disabled: !walletOk },\n        { id: \"card\", emoji: \"\ud83d\udcb3\", title: \"Card\", sub: savedCard ? `Pay using ${savedCard.label}` : \"No card saved \u2014 you'll be asked to add one\", disabled: false },\n        { id: \"cod\", emoji: \"\ud83d\udcb5\", title: \"Cash on Delivery\", sub: \"Pay when your order arrives\", disabled: false },\n      ];\n\n      if (options.find(o => o.id === _payMethod)?.disabled) _payMethod = \"upi\";\n\n      list.innerHTML = options.map(o => `\n    <button type=\"button\" class=\"pay-method-option ${_payMethod === o.id ? \"selected\" : \"\"} ${o.disabled ? \"disabled\" : \"\"}\" data-id=\"${o.id}\" ${o.disabled ? \"disabled\" : \"\"}>\n      <span class=\"pm-radio\"></span>\n      <span class=\"pm-emoji\">${o.emoji}</span>\n      <span class=\"pm-body\">\n        <span class=\"pm-title\">${o.title}</span>\n        <span class=\"pm-sub\">${o.sub}</span>\n      </span>\n    </button>\n  `).join(\"\");\n\n      list.querySelectorAll(\".pay-method-option\").forEach(btn => {\n        if (btn.disabled) return;\n        btn.onclick = () => {\n          _payMethod = btn.dataset.id;\n          renderPaymentMethodOptions();\n        };\n      });\n    }\n\n    const PAY_METHOD_PROCESSING = {\n      upi: \"Confirming with your UPI app\u2026\",\n      wallet: \"Deducting from your wallet\u2026\",\n      card: \"Charging your card\u2026\",\n      cod: \"Confirming your order\u2026\",\n    };\n\n    async function handlePayMethodSubmit() {\n      const errEl = document.getElementById(\"payMethodError\");\n      errEl.style.display = \"none\";\n\n      if (_payMethod === \"wallet\" && _walletBalance < _payMethodTotal) {\n        errEl.textContent = \"Insufficient wallet balance. Choose another method or add money to your wallet.\";\n        errEl.style.display = \"block\";\n        renderPaymentMethodOptions();\n        return;\n      }\n\n      // UPI/card need a saved detail first \u2014 bounce to the relevant \"add\" modal, then resume here\n      if (_payMethod === \"upi\" && !_paymentMethods.some(p => p.type === \"upi\")) {\n        _pendingCheckoutMethod = \"upi\";\n        closePaymentMethod();\n        openAddUpi();\n        toast(\"Add a UPI ID to continue\");\n        return;\n      }\n      if (_payMethod === \"card\" && !_paymentMethods.some(p => p.type === \"card\")) {\n        _pendingCheckoutMethod = \"card\";\n        closePaymentMethod();\n        openAddCard();\n        toast(\"Add a card to continue\");\n        return;\n      }\n\n      const submitBtn = document.getElementById(\"payMethodSubmit\");\n      submitBtn.disabled = true;\n      submitBtn.textContent = PAY_METHOD_PROCESSING[_payMethod] || \"Processing\u2026\";\n      const method = _payMethod;\n\n      try {\n        await placeOrder(method);\n      } finally {\n        submitBtn.disabled = false;\n        submitBtn.textContent = \"Place order\";\n        closePaymentMethod();\n      }\n    }\n\n    /**\n     * Creates the REAL order on the backend (server recomputes every price/discount/fee\n     * from the database \u2014 the client's numbers below are for display only). For upi/card,\n     * opens Razorpay's TEST-mode checkout and only shows \"paid\" after the backend has\n     * independently verified the payment signature.\n     */\n    async function placeOrder(paymentMethod) {\n      const method = paymentMethod || \"cod\";\n      const cart = getCart();\n      if (cart.length === 0) return;\n      const itemCount = cart.reduce((s, l) => s + l.qty, 0);\n\n      let order;\n      try {\n        const resp = await apiFetch(\"/orders\", {\n          method: \"POST\",\n          body: {\n            items: cart.map(l => ({ id: l.id, qty: l.qty })),\n            address: { name: _address.name, phone: _address.phone, line: _address.line },\n            paymentMethod: method,\n            couponCode: _appliedCoupon ? _appliedCoupon.code : null,\n          },\n        });\n        order = resp.order;\n      } catch (err) {\n        toast(err.message || \"Couldn't place your order. Please try again.\");\n        openPaymentMethod();\n        return;\n      }\n\n      if (method === \"wallet\") _walletBalance = Math.max(0, _walletBalance - order.total);\n\n      saveCart([]);\n      _appliedCoupon = null;\n      closeCart();\n\n      if (method === \"upi\" || method === \"card\") {\n        await payOrderWithRazorpay(order); // shows tracking UI itself once verified/failed\n      } else {\n        showOrderTracking(order, order.paymentStatus === \"paid\");\n      }\n    }\n\n    /** Opens Razorpay's checkout widget for an already-created (pending-payment) order. */\n    async function payOrderWithRazorpay(order) {\n      let session;\n      try {\n        session = await apiFetch(`/payments/create/${order._id}`, { method: \"POST\" });\n      } catch (err) {\n        toast(err.message || \"Couldn't start payment. You can retry from My Orders.\");\n        showOrderTracking(order, false);\n        return;\n      }\n\n      if (typeof Razorpay === \"undefined\") {\n        toast(\"Payment widget failed to load \u2014 check your connection and retry from My Orders.\");\n        showOrderTracking(order, false);\n        return;\n      }\n\n      const rzp = new Razorpay({\n        key: session.keyId,\n        amount: session.amount,\n        currency: session.currency,\n        order_id: session.razorpayOrderId,\n        name: \"SwiftCart\",\n        description: `Order ${order._id}`,\n        prefill: { name: _address.name, contact: _address.phone },\n        theme: { color: \"#3D5AFE\" },\n        handler: async (response) => {\n          try {\n            const { order: verified } = await apiFetch(\"/payments/verify\", { method: \"POST\", body: response });\n            toast(`Paid \u20b9${verified.total} via ${PAY_METHOD_LABELS[order.paymentMethod]} \ud83c\udf89`);\n            showOrderTracking(verified, true);\n          } catch (err) {\n            toast(\"Payment could not be verified. If money was deducted, it will be reconciled \u2014 check My Orders.\");\n            showOrderTracking(order, false);\n          }\n        },\n        modal: {\n          ondismiss: () => {\n            toast(\"Payment cancelled \u2014 order saved as unpaid. Retry anytime from My Orders.\");\n            showOrderTracking(order, false);\n          },\n        },\n      });\n      rzp.on(\"payment.failed\", () => {\n        toast(\"Payment failed. You can retry from My Orders.\");\n        showOrderTracking(order, false);\n      });\n      rzp.open();\n    }\n\n    function showOrderTracking(order, paid) {\n      const method = order.paymentMethod;\n      document.getElementById(\"trackOrderId\").textContent = `Order #${order._id.slice(-8).toUpperCase()}`;\n      document.getElementById(\"trackCount\").textContent = order.itemCount;\n      document.getElementById(\"trackAmount\").textContent = `\u20b9${order.total}`;\n      document.getElementById(\"trackTotalLabel\").textContent = paid ? \"total paid\" : \"amount due\";\n      const badgeEl = document.getElementById(\"trackPayStatus\");\n      badgeEl.className = \"track-pay-badge \" + (paid ? \"paid\" : \"due\");\n      badgeEl.textContent = paid ? `\u2705 Paid via ${PAY_METHOD_LABELS[method]}` : `\ud83d\udcb5 ${method === \"cod\" ? \"Pay \u20b9\" + order.total + \" on delivery\" : \"Payment pending \u2014 retry from My Orders\"}`;\n      document.getElementById(\"trackAddrName\").textContent = `${order.address.name} \u00b7 ${order.address.phone}`;\n      document.getElementById(\"trackAddrLine\").textContent = order.address.line;\n\n      runTrackingAnimation(order);\n      document.getElementById(\"trackOverlay\").classList.add(\"show\");\n      if (method === \"cod\") toast(`Order placed \u2014 pay \u20b9${order.total} on delivery`);\n    }\n\n    function runTrackingAnimation(order) {\n      _trackTimers.forEach(t => clearTimeout(t));\n      _trackTimers = [];\n\n      const stages = [\n        { pct: 8, rider: 8, status: \"Order placed\", eta: \"Arriving in 12 minutes\" },\n        { pct: 35, rider: 35, status: \"Packing your order\u2026\", eta: \"Arriving in 9 minutes\" },\n        { pct: 75, rider: 75, status: \"Out for delivery \ud83d\udef5\", eta: \"Arriving in 4 minutes\" },\n        { pct: 100, rider: 100, status: \"Delivered! Enjoy \ud83c\udf89\", eta: \"Delivered just now\" },\n      ];\n      const dots = document.querySelectorAll(\"#trackStages .track-stage\");\n      const fill = document.getElementById(\"trackFill\");\n      const rider = document.getElementById(\"trackRider\");\n      const statusEl = document.getElementById(\"trackStatus\");\n      const etaEl = document.getElementById(\"trackEta\");\n\n      dots.forEach(d => d.classList.remove(\"done\", \"active\"));\n      fill.style.width = \"0%\";\n      rider.style.left = \"0%\";\n\n      stages.forEach((s, i) => {\n        const timer = setTimeout(() => {\n          fill.style.width = s.pct + \"%\";\n          rider.style.left = s.rider + \"%\";\n          statusEl.textContent = s.status;\n          etaEl.textContent = s.eta;\n          dots.forEach((d, di) => {\n            d.classList.toggle(\"done\", di < i || (di === i && i === stages.length - 1));\n            d.classList.toggle(\"active\", di === i && i !== stages.length - 1);\n          });\n          if (i === stages.length - 1) {\n            toast(\"Delivered! \ud83c\udf89\");\n            if (order) order.status = \"Delivered\";\n          }\n        }, i * 1400);\n        _trackTimers.push(timer);\n      });\n    }\n\n    function closeTracking() {\n      document.getElementById(\"trackOverlay\").classList.remove(\"show\");\n      _trackTimers.forEach(t => clearTimeout(t));\n    }\n\n    /* ============ PROFILE SCREEN ============ */\n    let _hideOOS = false;\n\n    function openProfile() {\n      const user = getSession();\n      if (!user) { openAuth(\"login\"); return; }\n      document.getElementById(\"profileAvatar\").textContent = user.name.charAt(0).toUpperCase();\n      document.getElementById(\"profileName\").textContent = user.name;\n      document.getElementById(\"profileEmail\").textContent = user.email;\n      document.getElementById(\"profileOverlay\").classList.add(\"show\");\n    }\n    function closeProfile() { document.getElementById(\"profileOverlay\").classList.remove(\"show\"); }\n\n    function toggleHideOOS() {\n      _hideOOS = !_hideOOS;\n      document.getElementById(\"hideStockSwitch\").classList.toggle(\"on\", _hideOOS);\n      toast(_hideOOS ? \"Out-of-stock items hidden\" : \"Showing all items\");\n    }\n\n    /* ============ ORDERS SCREEN ============ */\n    function openOrders() {\n      const user = getSession();\n      if (!user) { openAuth(\"login\"); return; }\n      renderOrders();\n      document.getElementById(\"ordersOverlay\").classList.add(\"show\");\n    }\n    function closeOrders() { document.getElementById(\"ordersOverlay\").classList.remove(\"show\"); }\n\n    const ORDER_STATUS_LABEL = {\n      placed: \"Order placed\", packing: \"Packing\", out_for_delivery: \"Out for delivery \ud83d\udef5\",\n      delivered: \"Delivered\", cancelled: \"Cancelled\",\n    };\n\n    async function renderOrders() {\n      const list = document.getElementById(\"ordersList\");\n      list.innerHTML = `<div class=\"orders-empty\"><div class=\"e\">\u23f3</div>Loading your orders\u2026</div>`;\n\n      let mine;\n      try {\n        const resp = await apiFetch(\"/users/me/orders\"); // server scopes this to the logged-in user only\n        mine = resp.orders;\n      } catch (err) {\n        list.innerHTML = `<div class=\"orders-empty\"><div class=\"e\">\u26a0\ufe0f</div>Couldn't load your orders. Please try again.</div>`;\n        return;\n      }\n\n      if (mine.length === 0) {\n        list.innerHTML = `\n      <div class=\"orders-empty\">\n        <div class=\"e\">\ud83d\uded2</div>\n        No orders yet.<br/>Everything you order will show up here.\n        <div><button class=\"btn-primary\" id=\"ordersShopBtn\">Start shopping</button></div>\n      </div>`;\n        document.getElementById(\"ordersShopBtn\").onclick = () => { closeOrders(); closeProfile(); scrollToShop(); };\n        return;\n      }\n\n      list.innerHTML = mine.map(o => {\n        const itemsText = o.items.map(it => `${it.emoji} ${it.title} \u00d7${it.qty}`).join(\" \u00b7 \");\n        const dateText = new Date(o.createdAt).toLocaleDateString(undefined, { day: \"numeric\", month: \"short\", year: \"numeric\" });\n        const statusClass = o.orderStatus === \"delivered\" ? \"delivered\" : \"transit\";\n        const payLabel = o.paymentMethod ? (PAY_METHOD_LABELS[o.paymentMethod] || o.paymentMethod) : null;\n        const paid = o.paymentStatus === \"paid\";\n        return `\n      <div class=\"order-card\">\n        <div class=\"order-card-top\">\n          <div>\n            <div class=\"oid\">Order #${o._id.slice(-8).toUpperCase()}</div>\n            <div class=\"odate\">${dateText} \u00b7 ${o.address.line}</div>\n          </div>\n          <span class=\"order-status ${statusClass}\">${ORDER_STATUS_LABEL[o.orderStatus] || o.orderStatus}</span>\n        </div>\n        <div class=\"order-items\">${itemsText}</div>\n        <div class=\"order-card-foot\">\n          <span style=\"display:flex;align-items:center;gap:6px;flex-wrap:wrap\">\n            <span>${o.itemCount} item${o.itemCount > 1 ? \"s\" : \"\"}${o.couponCode ? ` \u00b7 \ud83c\udff7\ufe0f ${o.couponCode}` : \"\"}${payLabel ? ` \u00b7 ${payLabel}` : \"\"}</span>\n            ${payLabel ? `<span class=\"order-pay-badge ${paid ? \"paid\" : \"due\"}\">${paid ? \"Paid\" : (o.paymentMethod === \"cod\" ? \"Due on delivery\" : \"Payment pending\")}</span>` : \"\"}\n          </span>\n          <b>\u20b9${o.total}</b>\n        </div>\n      </div>`;\n      }).join(\"\");\n    }\n\n    /* ============ WISHLIST ============ */\n    function toggleWishlist(id) {\n      const i = _wishlist.indexOf(id);\n      if (i === -1) { _wishlist.push(id); toast(\"Added to wishlist \u2764\ufe0f\"); }\n      else { _wishlist.splice(i, 1); toast(\"Removed from wishlist\"); }\n      // Update just this product's heart button(s) in place instead of re-rendering\n      // the whole grid \u2014 avoids the flicker/\"page reload\" look on every click.\n      const isActive = _wishlist.includes(id);\n      document.querySelectorAll(`.wish-btn[data-id=\"${id}\"]`).forEach(btn => {\n        btn.classList.toggle(\"active\", isActive);\n        const svg = btn.querySelector(\"svg\");\n        if (svg) svg.setAttribute(\"fill\", isActive ? \"currentColor\" : \"none\");\n      });\n      if (document.getElementById(\"wishlistOverlay\").classList.contains(\"show\")) renderWishlist();\n    }\n\n    function openWishlist() {\n      renderWishlist();\n      document.getElementById(\"wishlistOverlay\").classList.add(\"show\");\n    }\n    function closeWishlist() { document.getElementById(\"wishlistOverlay\").classList.remove(\"show\"); }\n\n    function renderWishlist() {\n      const list = document.getElementById(\"wishlistList\");\n      const items = PRODUCTS.filter(p => _wishlist.includes(p.id));\n\n      if (items.length === 0) {\n        list.innerHTML = `\n      <div class=\"orders-empty\">\n        <div class=\"e\">\ud83e\udd0d</div>\n        Your wishlist is empty.<br/>Tap the heart on any product to save it here.\n        <div><button class=\"btn-primary\" id=\"wishlistShopBtn\">Browse products</button></div>\n      </div>`;\n        document.getElementById(\"wishlistShopBtn\").onclick = () => { closeWishlist(); scrollToShop(); };\n        return;\n      }\n\n      list.innerHTML = items.map(p => `\n    <div class=\"order-card\">\n      <div class=\"order-card-top\">\n        <div style=\"display:flex;align-items:center;gap:12px\">\n          <div style=\"width:44px;height:44px;border-radius:10px;overflow:hidden;background:var(--surface);display:flex;align-items:center;justify-content:center;font-size:22px;flex:none\">\n            <img src=\"${p.img}\" alt=\"${p.title}\" style=\"width:100%;height:100%;object-fit:cover\" onerror=\"this.replaceWith(document.createTextNode('${p.emoji}'))\" />\n          </div>\n          <div>\n            <div class=\"oid\" style=\"font-size:14px\">${p.title}</div>\n            <div class=\"odate\">\u20b9${p.price}${p.old ? ` <s>\u20b9${p.old}</s>` : \"\"}</div>\n          </div>\n        </div>\n        <button class=\"wish-btn active\" data-id=\"${p.id}\" style=\"position:static;background:none;box-shadow:none\" aria-label=\"Remove from wishlist\">\n          <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"currentColor\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M19 14c1.5-1.5 3-3.4 3-5.5A5.5 5.5 0 0 0 12 5a5.5 5.5 0 0 0-10 3.5C2 10.6 3.5 12.5 5 14l7 7Z\"/></svg>\n        </button>\n      </div>\n      <div class=\"order-card-foot\" style=\"border-top:none;padding-top:2px\">\n        <button class=\"add-btn\" style=\"background:var(--bolt-500);color:#fff;padding:9px 16px;width:100%\" data-id=\"${p.id}\">Add to cart</button>\n      </div>\n    </div>\n  `).join(\"\");\n\n      list.querySelectorAll(\".wish-btn\").forEach(btn => {\n        btn.onclick = () => toggleWishlist(parseInt(btn.dataset.id));\n      });\n      list.querySelectorAll(\".add-btn\").forEach(btn => {\n        btn.onclick = () => addToCart(parseInt(btn.dataset.id));\n      });\n    }\n\n    /* ============ INFO PAGES (About / Return Policy / Disclaimer) ============ */\n    function openAbout() { document.getElementById(\"aboutOverlay\").classList.add(\"show\"); }\n    function closeAbout() { document.getElementById(\"aboutOverlay\").classList.remove(\"show\"); }\n\n    function openReturnPolicy() { document.getElementById(\"returnOverlay\").classList.add(\"show\"); }\n    function closeReturnPolicy() { document.getElementById(\"returnOverlay\").classList.remove(\"show\"); }\n\n    function openDisclaimer() { document.getElementById(\"disclaimerOverlay\").classList.add(\"show\"); }\n    function closeDisclaimer() { document.getElementById(\"disclaimerOverlay\").classList.remove(\"show\"); }\n\n    /* ============ COUPONS SCREEN ============ */\n    function openCoupons() {\n      renderCoupons();\n      document.getElementById(\"couponsOverlay\").classList.add(\"show\");\n    }\n    function closeCoupons() { document.getElementById(\"couponsOverlay\").classList.remove(\"show\"); }\n\n    function renderCoupons() {\n      const list = document.getElementById(\"couponsList\");\n      const cart = getCart();\n      const subtotal = cart.reduce((s, l) => { const p = PRODUCTS.find(pp => pp.id === l.id); return s + p.price * l.qty; }, 0);\n\n      const knownHtml = COUPONS.map(c => {\n        const eligible = subtotal >= c.minSubtotal;\n        const applied = _appliedCoupon && _appliedCoupon.code === c.code;\n        return `\n      <div class=\"order-card\">\n        <div class=\"order-card-top\">\n          <div>\n            <div class=\"oid\" style=\"font-size:14px\">\ud83c\udff7\ufe0f ${c.code} \u2014 ${c.label}</div>\n            <div class=\"odate\">${c.desc}</div>\n          </div>\n          ${applied ? `<span class=\"order-status delivered\">Applied</span>` : \"\"}\n        </div>\n        <div class=\"order-card-foot\" style=\"border-top:none;padding-top:2px\">\n          <button class=\"add-btn\" style=\"background:${applied || !eligible ? \"#E2E8F0\" : \"var(--bolt-500)\"};color:${applied || !eligible ? \"var(--ink-soft)\" : \"#fff\"};padding:9px 16px;width:100%\" data-code=\"${c.code}\" ${applied || !eligible ? \"disabled\" : \"\"}>\n            ${applied ? \"Applied to cart\" : eligible ? \"Apply to cart\" : `Need \u20b9${c.minSubtotal - subtotal} more`}\n          </button>\n        </div>\n      </div>`;\n      }).join(\"\");\n\n      // codes the user saved for later that aren't already part of the built-in catalog\n      const customSaved = _savedCoupons.filter(code => !COUPONS.some(c => c.code === code));\n      let savedHtml = \"\";\n      if (customSaved.length) {\n        savedHtml = `<div class=\"plist-head\" style=\"margin:16px 0 8px\">Saved for later</div>` + customSaved.map(code => {\n          const applied = _appliedCoupon && _appliedCoupon.code === code;\n          return `\n        <div class=\"order-card\">\n          <div class=\"order-card-top\">\n            <div>\n              <div class=\"oid\" style=\"font-size:14px\">\ud83c\udff7\ufe0f ${code}</div>\n              <div class=\"odate\">Saved code \u2014 apply it whenever you're ready</div>\n            </div>\n            ${applied ? `<span class=\"order-status delivered\">Applied</span>` : \"\"}\n          </div>\n          <div class=\"order-card-foot\" style=\"border-top:none;padding-top:2px;display:flex;gap:8px\">\n            <button class=\"add-btn\" style=\"background:${applied ? \"#E2E8F0\" : \"var(--bolt-500)\"};color:${applied ? \"var(--ink-soft)\" : \"#fff\"};padding:9px 16px;flex:1\" data-code=\"${code}\" ${applied ? \"disabled\" : \"\"}>\n              ${applied ? \"Applied to cart\" : \"Apply to cart\"}\n            </button>\n            <button class=\"saved-remove-btn\" data-code=\"${code}\" aria-label=\"Remove saved code\" style=\"padding:9px 12px;border-radius:10px;border:1px solid var(--line);background:#fff\">\u2715</button>\n          </div>\n        </div>`;\n        }).join(\"\");\n      }\n\n      list.innerHTML = knownHtml + savedHtml;\n\n      list.querySelectorAll(\".add-btn\").forEach(btn => {\n        if (btn.disabled) return;\n        btn.onclick = () => applyCouponCode(btn.dataset.code);\n      });\n      list.querySelectorAll(\".saved-remove-btn\").forEach(btn => {\n        btn.onclick = () => removeSavedCoupon(btn.dataset.code);\n      });\n    }\n\n    /* ============ WALLET ============ */\n    let _walletBalance = 0;\n    let _walletTx = []; // { id, amount, method, date }\n    let _walletTxCounter = 1;\n    let _upiSelectedAmt = null;\n\n    function openWallet() {\n      renderWallet();\n      document.getElementById(\"walletOverlay\").classList.add(\"show\");\n    }\n    function closeWallet() { document.getElementById(\"walletOverlay\").classList.remove(\"show\"); }\n\n    function renderWallet() {\n      document.getElementById(\"walletBalanceAmt\").textContent = `\u20b9${_walletBalance}`;\n      const list = document.getElementById(\"walletTxList\");\n      if (_walletTx.length === 0) {\n        list.innerHTML = `<div class=\"orders-empty\" style=\"padding:30px 10px\">\n      <div class=\"e\">\ud83d\udcb3</div>No activity yet.<br/>Add money to get started.\n    </div>`;\n        return;\n      }\n      list.innerHTML = _walletTx.map(tx => {\n        const isDebit = tx.type === \"debit\";\n        const title = isDebit ? tx.title : \"Added via UPI\";\n        const detail = isDebit\n          ? tx.date.toLocaleDateString(undefined, { day: \"numeric\", month: \"short\" })\n          : `${tx.upiId ? tx.upiId + \" \u00b7 \" : \"\"}${tx.date.toLocaleDateString(undefined, { day: \"numeric\", month: \"short\" })}`;\n        const arrowPath = isDebit ? `<path d=\"M12 19V5\"/><path d=\"m5 12 7-7 7 7\"/>` : `<path d=\"M12 5v14\"/><path d=\"m19 12-7 7-7-7\"/>`;\n        return `\n    <div class=\"wallet-tx${isDebit ? \" debit\" : \"\"}\">\n      <div class=\"icon\">\n        <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">${arrowPath}</svg>\n      </div>\n      <div class=\"mid\">\n        <div class=\"t\">${title}</div>\n        <div class=\"d\">${detail}</div>\n      </div>\n      <div class=\"amt\">${isDebit ? \"\u2212\" : \"+\"}\u20b9${tx.amount}</div>\n    </div>`;\n      }).join(\"\");\n    }\n\n    function openWalletAdd() {\n      _upiSelectedAmt = null;\n      document.getElementById(\"upiAmount\").value = \"\";\n      document.getElementById(\"upiId\").value = \"\";\n      document.getElementById(\"walletAddError\").style.display = \"none\";\n      document.getElementById(\"upiChipRow\").querySelectorAll(\".upi-chip\").forEach(c => c.classList.remove(\"active\"));\n      document.getElementById(\"walletAddOverlay\").classList.add(\"show\");\n    }\n    function closeWalletAdd() { document.getElementById(\"walletAddOverlay\").classList.remove(\"show\"); }\n\n    async function handleWalletAddSubmit() {\n      const errEl = document.getElementById(\"walletAddError\");\n      errEl.style.display = \"none\";\n      const amount = parseInt(document.getElementById(\"upiAmount\").value, 10);\n      const upiId = document.getElementById(\"upiId\").value.trim();\n\n      if (!amount || amount <= 0) {\n        errEl.textContent = \"Please enter a valid amount.\";\n        errEl.style.display = \"block\";\n        return;\n      }\n      if (!upiId || !/^[\\w.\\-]+@[\\w.\\-]+$/.test(upiId)) {\n        errEl.textContent = \"Please enter a valid UPI ID (e.g. name@upi).\";\n        errEl.style.display = \"block\";\n        return;\n      }\n      if (typeof Razorpay === \"undefined\") {\n        errEl.textContent = \"Payment widget failed to load. Check your connection and try again.\";\n        errEl.style.display = \"block\";\n        return;\n      }\n\n      const submitBtn = document.getElementById(\"walletAddSubmit\");\n      submitBtn.disabled = true;\n      submitBtn.textContent = \"Opening secure payment\u2026\";\n\n      let session;\n      try {\n        session = await apiFetch(\"/payments/wallet/topup/create\", { method: \"POST\", body: { amount } });\n      } catch (err) {\n        errEl.textContent = err.message || \"Couldn't start payment. Please try again.\";\n        errEl.style.display = \"block\";\n        submitBtn.disabled = false;\n        submitBtn.textContent = \"Pay via UPI\";\n        return;\n      }\n\n      submitBtn.disabled = false;\n      submitBtn.textContent = \"Pay via UPI\";\n\n      const rzp = new Razorpay({\n        key: session.keyId,\n        amount: session.amount,\n        currency: session.currency,\n        order_id: session.razorpayOrderId,\n        name: \"SwiftCart\",\n        description: \"Add money to wallet\",\n        prefill: { vpa: upiId },\n        theme: { color: \"#3D5AFE\" },\n        handler: async (response) => {\n          try {\n            const result = await apiFetch(\"/payments/wallet/topup/verify\", {\n              method: \"POST\",\n              body: { ...response, amount },\n            });\n            _walletBalance = result.walletBalance; // authoritative value from the server, not the amount we guessed client-side\n            _walletTxCounter++;\n            _walletTx.unshift({ id: _walletTxCounter, amount, type: \"credit\", upiId, date: new Date() });\n            closeWalletAdd();\n            renderWallet();\n            toast(`\u20b9${amount} added to your wallet \ud83c\udf89`);\n          } catch (err) {\n            toast(\"Payment could not be verified. If money was deducted, contact support.\");\n          }\n        },\n        modal: { ondismiss: () => toast(\"Add-money payment cancelled\") },\n      });\n      rzp.on(\"payment.failed\", () => toast(\"Payment failed. Please try again.\"));\n      rzp.open();\n    }\n    document.getElementById(\"signInBtn\").onclick = () => openAuth(\"login\");\n    document.getElementById(\"heroSignIn\").onclick = () => document.getElementById(\"categories\").scrollIntoView({ behavior: \"smooth\", block: \"center\" });\n    document.getElementById(\"authClose\").onclick = closeAuth;\n    document.getElementById(\"authOverlay\").onclick = (e) => { if (e.target.id === \"authOverlay\") closeAuth(); };\n    document.getElementById(\"authForm\").onsubmit = handleAuthSubmit;\n    document.getElementById(\"authSubmit\").onclick = handleAuthSubmit;\n    document.getElementById(\"authPassword\").addEventListener(\"keydown\", (e) => { if (e.key === \"Enter\") handleAuthSubmit(e); });\n\n    document.getElementById(\"cartBtn\").onclick = openCart;\n    document.getElementById(\"closeCart\").onclick = closeCart;\n    document.getElementById(\"overlay\").onclick = closeCart;\n\n    document.getElementById(\"userBtn\").onclick = () => document.getElementById(\"userMenu\").classList.toggle(\"open\");\n    document.addEventListener(\"click\", (e) => {\n      const wrap = document.getElementById(\"userMenuWrap\");\n      if (!wrap.contains(e.target)) document.getElementById(\"userMenu\").classList.remove(\"open\");\n    });\n    document.getElementById(\"logoutBtn\").onclick = () => { document.getElementById(\"userMenu\").classList.remove(\"open\"); logout(); };\n    document.getElementById(\"myOrdersBtn\").onclick = () => { document.getElementById(\"userMenu\").classList.remove(\"open\"); openOrders(); };\n    document.getElementById(\"profileBtn\").onclick = () => { document.getElementById(\"userMenu\").classList.remove(\"open\"); openProfile(); };\n\n    document.getElementById(\"profileBack\").onclick = closeProfile;\n    document.getElementById(\"ordersBack\").onclick = closeOrders;\n    document.getElementById(\"wishlistBack\").onclick = closeWishlist;\n    document.getElementById(\"couponsBack\").onclick = closeCoupons;\n    document.getElementById(\"addrBookBack\").onclick = closeAddressBook;\n    document.getElementById(\"addAddressBtn\").onclick = () => { _editingAddrId = null; openAddress(\"add\"); };\n    document.getElementById(\"hideStockSwitch\").onclick = toggleHideOOS;\n    document.getElementById(\"qaOrders\").onclick = openOrders;\n    document.getElementById(\"qaWallet\").onclick = () => { closeProfile(); openWallet(); };\n    document.getElementById(\"qaHelp\").onclick = () => toast(\"Support chat coming soon\");\n    document.getElementById(\"rowAddress\").onclick = () => { closeProfile(); openAddressBook(); };\n    document.getElementById(\"rowWishlist\").onclick = () => { closeProfile(); openWishlist(); };\n    document.getElementById(\"rowWallet2\").onclick = () => { closeProfile(); openWallet(); };\n    document.getElementById(\"walletBack\").onclick = closeWallet;\n    document.getElementById(\"walletAddBtn\").onclick = openWalletAdd;\n    document.getElementById(\"walletAddClose\").onclick = closeWalletAdd;\n    document.getElementById(\"walletAddOverlay\").onclick = (e) => { if (e.target.id === \"walletAddOverlay\") closeWalletAdd(); };\n    document.getElementById(\"walletAddSubmit\").onclick = handleWalletAddSubmit;\n    document.getElementById(\"upiChipRow\").querySelectorAll(\".upi-chip\").forEach(chip => {\n      chip.onclick = () => {\n        document.getElementById(\"upiChipRow\").querySelectorAll(\".upi-chip\").forEach(c => c.classList.remove(\"active\"));\n        chip.classList.add(\"active\");\n        document.getElementById(\"upiAmount\").value = chip.dataset.amt;\n      };\n    });\n    document.getElementById(\"rowPayment\").onclick = () => { closeProfile(); openPaymentSettings(); };\n    document.getElementById(\"rowCoupons\").onclick = () => { closeProfile(); openCoupons(); };\n\n    document.getElementById(\"paymentBack\").onclick = closePaymentSettings;\n    document.getElementById(\"addUpiBtn\").onclick = openAddUpi;\n    document.getElementById(\"addUpiClose\").onclick = closeAddUpi;\n    document.getElementById(\"addUpiOverlay\").onclick = (e) => { if (e.target.id === \"addUpiOverlay\") closeAddUpi(); };\n    document.getElementById(\"addUpiSubmit\").onclick = handleAddUpiSubmit;\n    document.getElementById(\"pmUpiId\").addEventListener(\"keydown\", (e) => { if (e.key === \"Enter\") handleAddUpiSubmit(); });\n\n    document.getElementById(\"addCardBtn\").onclick = openAddCard;\n    document.getElementById(\"addCardClose\").onclick = closeAddCard;\n    document.getElementById(\"addCardOverlay\").onclick = (e) => { if (e.target.id === \"addCardOverlay\") closeAddCard(); };\n    document.getElementById(\"addCardSubmit\").onclick = handleAddCardSubmit;\n    document.getElementById(\"pmCardNumber\").addEventListener(\"input\", (e) => {\n      e.target.value = e.target.value.replace(/[^\\d]/g, \"\").replace(/(.{4})/g, \"$1 \").trim();\n    });\n    document.getElementById(\"pmCardExpiry\").addEventListener(\"input\", (e) => {\n      let v = e.target.value.replace(/[^\\d]/g, \"\").slice(0, 4);\n      if (v.length > 2) v = v.slice(0, 2) + \"/\" + v.slice(2);\n      e.target.value = v;\n    });\n\n    document.getElementById(\"saveCouponBtn\").onclick = () => saveCouponForLater(document.getElementById(\"saveCouponInput\").value);\n    document.getElementById(\"saveCouponInput\").addEventListener(\"keydown\", (e) => {\n      if (e.key === \"Enter\") saveCouponForLater(e.target.value);\n    });\n    document.getElementById(\"rowShare\").onclick = () => toast(\"Link copied \u2014 share SwiftCart with friends!\");\n    document.getElementById(\"rowAbout\").onclick = () => toast(\"SwiftCart - everything, delivered fast\");\n    document.getElementById(\"rowNotif\").onclick = () => toast(\"Notification preferences saved\");\n    document.getElementById(\"rowLogout\").onclick = () => { closeProfile(); logout(); };\n\n    document.getElementById(\"footerAboutBtn\").onclick = openAbout;\n    document.getElementById(\"footerReturnBtn\").onclick = openReturnPolicy;\n    document.getElementById(\"footerDisclaimerBtn\").onclick = openDisclaimer;\n    document.getElementById(\"aboutBack\").onclick = closeAbout;\n    document.getElementById(\"returnBack\").onclick = closeReturnPolicy;\n    document.getElementById(\"disclaimerBack\").onclick = closeDisclaimer;\n    document.getElementById(\"aboutShopBtn\").onclick = () => { closeAbout(); scrollToShop(); };\n    document.getElementById(\"returnShopBtn\").onclick = () => { closeReturnPolicy(); scrollToShop(); };\n    document.getElementById(\"disclaimerShopBtn\").onclick = () => { closeDisclaimer(); scrollToShop(); };\n\n    document.getElementById(\"checkoutBtn\").onclick = () => {\n      if (!getSession()) { closeCart(); openAuth(\"login\"); toast(\"Sign in to check out\"); return; }\n      if (getCart().length === 0) return;\n      closeCart();\n      openAddress();\n    };\n\n    document.getElementById(\"addrClose\").onclick = closeAddress;\n    document.getElementById(\"addrOverlay\").onclick = (e) => { if (e.target.id === \"addrOverlay\") closeAddress(); };\n    document.getElementById(\"addrSubmit\").onclick = handleAddressSubmit;\n\n    document.getElementById(\"payMethodClose\").onclick = closePaymentMethod;\n    document.getElementById(\"payMethodOverlay\").onclick = (e) => { if (e.target.id === \"payMethodOverlay\") closePaymentMethod(); };\n    document.getElementById(\"payMethodSubmit\").onclick = handlePayMethodSubmit;\n\n    document.getElementById(\"trackClose\").onclick = closeTracking;\n    document.getElementById(\"trackOverlay\").onclick = (e) => { if (e.target.id === \"trackOverlay\") closeTracking(); };\n\n    document.getElementById(\"searchInput\").addEventListener(\"input\", (e) => renderGrid(e.target.value));\n    document.getElementById(\"mobileSearchBtn\").onclick = () => {\n      const row = document.getElementById(\"mobileSearchRow\");\n      row.classList.toggle(\"open\");\n      if (row.classList.contains(\"open\")) document.getElementById(\"mobileSearchInput\").focus();\n    };\n    document.getElementById(\"mobileSearchInput\").addEventListener(\"input\", (e) => renderGrid(e.target.value));\n    document.getElementById(\"mobileAccountBtn\").onclick = () => {\n      if (getSession()) { openProfile(); } else { openAuth(\"login\"); }\n    };\n\n    /* ============ INIT ============ */\n    restoreSession(); // GET /api/auth/me \u2014 restores login state on refresh via the session cookie\n    renderCategories();\n    renderGrid();\n    renderCart();\n    startTimer();\n  ";
